  { auto _e = PROVIDER_PEER_ID(); if (_e) _o->PROVIDER_PEER_ID = _e->str(); }
  { auto _e = PROVIDER_EPM_CID(); if (_e) _o->PROVIDER_EPM_CID = _e->str(); }
  { auto _e = TITLE(); if (_e) _o->TITLE = _e->str(); }
  { auto _e = DESCRIPTION(); if (_e) _o->DESCRIPTION = _e->str(); }
  { auto _e = DATA_TYPES(); if (_e) { _o->DATA_TYPES.resize(_e->size()); for (::flatbuffers::uoffset_t _i = 0; _i < _e->size(); _i++) { _o->DATA_TYPES[_i] = _e->Get(_i)->str(); } } else { _o->DATA_TYPES.resize(0); } }
