  { auto _e = SAMPLE_CID(); if (_e) _o->SAMPLE_CID = _e->str(); }
  { auto _e = ACCESS_TYPE(); _o->ACCESS_TYPE = _e; }
  { auto _e = ENCRYPTION_REQUIRED(); _o->ENCRYPTION_REQUIRED = _e; }
  { auto _e = PRICING(); if (_e) { _o->PRICING.resize(_e->size()); for (::flatbuffers::uoffset_t _i = 0; _i < _e->size(); _i++) { if(_o->PRICING[_i]) { _e->Get(_i)->UnPackTo(_o->PRICING[_i].get(), _resolver); } else { _o->PRICING[_i] = std::unique_ptr<PricingTierT>(_e->Get(_i)->UnPack(_resolver)); } } } else { _o->PRICING.resize(0); } }
  { auto _e = ACCEPTED_PAYMENTS(); if (_e) { _o->ACCEPTED_PAYMENTS.resize(_e->size()); for (::flatbuffers::uoffset_t _i = 0; _i < _e->size(); _i++) { _o->ACCEPTED_PAYMENTS[_i] = static_cast<paymentMethod>(_e->Get(_i)); } } else { _o->ACCEPTED_PAYMENTS.resize(0); } }
  { auto _e = CREATED_AT(); _o->CREATED_AT = _e; }
  { auto _e = UPDATED_AT(); _o->UPDATED_AT = _e; }
