inline ::flatbuffers::Offset<STF> CreateSTF(::flatbuffers::FlatBufferBuilder &_fbb, const STFT *_o, const ::flatbuffers::rehasher_function_t *_rehasher) {
  return STF::Pack(_fbb, _o, _rehasher);
}

inline ::flatbuffers::Offset<STF> STF::Pack(::flatbuffers::FlatBufferBuilder &_fbb, const STFT* _o, const ::flatbuffers::rehasher_function_t *_rehasher) {
  (void)_rehasher;
  (void)_o;
  struct _VectorArgs { ::flatbuffers::FlatBufferBuilder *__fbb; const STFT* __o; const ::flatbuffers::rehasher_function_t *__rehasher; } _va = { &_fbb, _o, _rehasher}; (void)_va;
  auto _LISTING_ID = _fbb.CreateString(_o->LISTING_ID);
  auto _PROVIDER_PEER_ID = _fbb.CreateString(_o->PROVIDER_PEER_ID);
  auto _PROVIDER_EPM_CID = _o->PROVIDER_EPM_CID.empty() ? 0 : _fbb.CreateString(_o->PROVIDER_EPM_CID);
  auto _TITLE = _fbb.CreateString(_o->TITLE);
  auto _DESCRIPTION = _o->DESCRIPTION.empty() ? 0 : _fbb.CreateString(_o->DESCRIPTION);
  auto _DATA_TYPES = _o->DATA_TYPES.size() ? _fbb.CreateVectorOfStrings(_o->DATA_TYPES) : 0;
  auto _COVERAGE = _o->COVERAGE ? CreateDataCoverage(_fbb, _o->COVERAGE.get(), _rehasher) : 0;
  auto _SAMPLE_CID = _o->SAMPLE_CID.empty() ? 0 : _fbb.CreateString(_o->SAMPLE_CID);
  auto _ACCESS_TYPE = _o->ACCESS_TYPE;
  auto _ENCRYPTION_REQUIRED = _o->ENCRYPTION_REQUIRED;
  auto _PRICING = _o->PRICING.size() ? _fbb.CreateVector<::flatbuffers::Offset<PricingTier>> (_o->PRICING.size(), [](size_t i, _VectorArgs *__va) { return CreatePricingTier(*__va->__fbb, __va->__o->PRICING[i].get(), __va->__rehasher); }, &_va ) : 0;
  auto _ACCEPTED_PAYMENTS = _o->ACCEPTED_PAYMENTS.size() ? _fbb.CreateVector(_o->ACCEPTED_PAYMENTS) : 0;
  auto _CREATED_AT = _o->CREATED_AT;
  auto _UPDATED_AT = _o->UPDATED_AT;
  auto _ACTIVE = _o->ACTIVE;
  auto _SIGNATURE = _o->SIGNATURE.size() ? _fbb.CreateVector(_o->SIGNATURE) : 0;
  return CreateSTF(
      _fbb,
      _LISTING_ID,
      _PROVIDER_PEER_ID,
      _PROVIDER_EPM_CID,
      _TITLE,
      _DESCRIPTION,
      _DATA_TYPES,
      _COVERAGE,
      _SAMPLE_CID,
      _ACCESS_TYPE,
      _ENCRYPTION_REQUIRED,
      _PRICING,
      _ACCEPTED_PAYMENTS,
      _CREATED_AT,
      _UPDATED_AT,
      _ACTIVE,
      _SIGNATURE);
}

inline const STF *GetSTF(const void *buf) {
  return ::flatbuffers::GetRoot<STF>(buf);
}

inline const STF *GetSizePrefixedSTF(const void *buf) {
  return ::flatbuffers::GetSizePrefixedRoot<STF>(buf);
}

inline const char *STFIdentifier() {
  return "$STF";
}

inline bool STFBufferHasIdentifier(const void *buf) {
  return ::flatbuffers::BufferHasIdentifier(
      buf, STFIdentifier());
}

inline bool SizePrefixedSTFBufferHasIdentifier(const void *buf) {
  return ::flatbuffers::BufferHasIdentifier(
      buf, STFIdentifier(), true);
}

template <bool B = false>
inline bool VerifySTFBuffer(
    ::flatbuffers::VerifierTemplate<B> &verifier) {
  return verifier.template VerifyBuffer<STF>(STFIdentifier());
}

template <bool B = false>
inline bool VerifySizePrefixedSTFBuffer(
    ::flatbuffers::VerifierTemplate<B> &verifier) {
  return verifier.template VerifySizePrefixedBuffer<STF>(STFIdentifier());
}

inline void FinishSTFBuffer(
    ::flatbuffers::FlatBufferBuilder &fbb,
    ::flatbuffers::Offset<STF> root) {
  fbb.Finish(root, STFIdentifier());
}

inline void FinishSizePrefixedSTFBuffer(
    ::flatbuffers::FlatBufferBuilder &fbb,
    ::flatbuffers::Offset<STF> root) {
  fbb.FinishSizePrefixed(root, STFIdentifier());
}

inline std::unique_ptr<STFT> UnPackSTF(
    const void *buf,
    const ::flatbuffers::resolver_function_t *res = nullptr) {
  return std::unique_ptr<STFT>(GetSTF(buf)->UnPack(res));
}

inline std::unique_ptr<STFT> UnPackSizePrefixedSTF(
    const void *buf,
    const ::flatbuffers::resolver_function_t *res = nullptr) {
  return std::unique_ptr<STFT>(GetSizePrefixedSTF(buf)->UnPack(res));
}

